create extension if not exists pgcrypto;
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;

create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,locale text not null default 'ko',timezone text,primary_airline_id text,onboarding_completed boolean not null default false,avatar_path text,recruitment_language text,app_preferences jsonb not null default '{}'::jsonb,last_active_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,new.raw_user_meta_data->>'display_name') on conflict(id) do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

create table if not exists public.onboarding_states(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,answers jsonb not null default '{}'::jsonb,diagnosis_result jsonb not null default '{}'::jsonb,completed boolean not null default false,legacy_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id));
create table if not exists public.career_experiences(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,legacy_id text,title text not null default '',category text not null default 'other',organization text,role text,period text,situation text not null default '',task text not null default '',action text not null default '',result text not null default '',learning text not null default '',short_summary text not null default '',competency_tags text[] not null default '{}',question_tags text[] not null default '{}',status text not null default 'draft',source text not null default 'manual',original_transcript text,source_experience_id uuid references public.career_experiences(id) on delete set null,usage_count int not null default 0,last_used_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id,legacy_id));
create table if not exists public.interview_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,legacy_id text,question_id text not null,category text not null,transcript text not null default '',duration_seconds int not null default 0,analysis jsonb not null default '{}'::jsonb,target_airline_id text,experience_id uuid references public.career_experiences(id) on delete set null,experience_snapshot jsonb not null default '{}'::jsonb,attempt_number int not null default 1,previous_attempt_id uuid references public.interview_attempts(id) on delete set null,completed boolean not null default false,audio_path text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id,legacy_id));
create table if not exists public.self_introduction_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,legacy_id text,transcript text not null default '',duration_seconds int not null default 0,analysis jsonb not null default '{}'::jsonb,target_airline_id text,experience_id uuid references public.career_experiences(id) on delete set null,experience_snapshot jsonb not null default '{}'::jsonb,attempt_number int not null default 1,previous_attempt_id uuid references public.self_introduction_attempts(id) on delete set null,completed boolean not null default false,audio_path text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id,legacy_id));
create table if not exists public.application_answers(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,legacy_id text,airline_id text,prompt_id text not null,custom_prompt text,document_type text not null,title text not null,status text not null default 'draft',selected_experience_ids jsonb not null default '[]'::jsonb,current_version_id uuid,source_context_snapshot jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id,legacy_id));
create table if not exists public.application_answer_versions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,answer_id uuid not null references public.application_answers(id) on delete cascade,version int not null,content text not null,character_count int not null default 0,word_count int not null default 0,evidence jsonb not null default '[]'::jsonb,analysis jsonb not null default '{}'::jsonb,change_reason text not null default 'manual_edit',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(answer_id,version));
alter table public.application_answers drop constraint if exists application_answers_current_version_id_fkey; alter table public.application_answers add constraint application_answers_current_version_id_fkey foreign key(current_version_id) references public.application_answer_versions(id) on delete set null;
create table if not exists public.learning_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,event_type text not null,source_entity_type text not null,source_entity_id text,duration_minutes int not null default 0,duration_source text not null default 'estimated',related_capability_keys text[] not null default '{}',capability_deltas jsonb not null default '{}'::jsonb,metadata jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now(),stable_key text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id,stable_key));
create table if not exists public.weekly_plans(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,week_start date not null,week_end date not null,status text not null default 'draft',priorities jsonb not null default '[]'::jsonb,routine_days jsonb not null default '[]'::jsonb,generated_from_activity_ids jsonb not null default '[]'::jsonb,confirmed_at timestamptz,revision int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id,week_start,revision));
create table if not exists public.user_settings(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,locale text not null default 'ko',timezone text,ai_text_consent boolean not null default false,ai_audio_consent boolean not null default false,airline_context_consent boolean not null default false,cloud_audio_preference text not null default 'ask_each_time' check(cloud_audio_preference in('ask_each_time','upload','local_only')),study_time text,primary_airline_id text,interested_airline_ids text[] not null default '{}',notification_preferences jsonb not null default '{}'::jsonb,provider_preference jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id));
create table if not exists public.sync_metadata(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,device_id text not null,last_sync_at timestamptz,last_pulled_at timestamptz,last_pushed_at timestamptz,app_schema_version int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id,device_id));
create table if not exists public.user_audio_files(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,entity_type text not null check(entity_type in('interview','self_introduction')),entity_id text not null,bucket text not null default 'cabin-training-audio',path text not null,mime_type text not null,size_bytes bigint not null,duration_seconds int,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,client_updated_at timestamptz not null default now(),schema_version int not null default 1,unique(user_id,path));

do $$ declare t text; begin foreach t in array array['profiles','onboarding_states','career_experiences','interview_attempts','self_introduction_attempts','application_answers','application_answer_versions','learning_events','weekly_plans','user_settings','sync_metadata','user_audio_files'] loop execute format('drop trigger if exists set_%I_updated_at on public.%I',t,t); execute format('create trigger set_%I_updated_at before update on public.%I for each row execute function public.set_updated_at()',t,t); end loop; end $$;
create index if not exists career_experiences_user_updated on public.career_experiences(user_id,updated_at desc); create index if not exists career_experiences_user_status on public.career_experiences(user_id,status); create index if not exists interview_attempts_user_created on public.interview_attempts(user_id,created_at desc); create index if not exists interview_question on public.interview_attempts(user_id,question_id); create index if not exists interview_previous on public.interview_attempts(previous_attempt_id); create index if not exists interview_experience on public.interview_attempts(experience_id); create index if not exists self_intro_user_created on public.self_introduction_attempts(user_id,created_at desc); create index if not exists application_user_airline on public.application_answers(user_id,airline_id); create index if not exists answer_versions_answer_version on public.application_answer_versions(answer_id,version desc); create index if not exists learning_user_occurred on public.learning_events(user_id,occurred_at desc); create index if not exists weekly_user_week on public.weekly_plans(user_id,week_start desc);
